green=colors.HexColor('#173c2b');mint=colors.HexColor('#e9f1e1');muted=colors.HexColor('#496044');gold=colors.HexColor('#fff2cd')
styles=getSampleStyleSheet();styles.add(ParagraphStyle(name='TitleOB',fontName='Helvetica-Bold',fontSize=26,leading=28,textColor=green,spaceAfter=12));styles.add(ParagraphStyle(name='DeckOB',fontName='Helvetica',fontSize=11,leading=16,textColor=muted,spaceAfter=12));styles.add(ParagraphStyle(name='HeadOB',fontName='Helvetica-Bold',fontSize=13,leading=16,textColor=green,spaceBefore=10,spaceAfter=6));styles.add(ParagraphStyle(name='BodyOB',fontName='Helvetica',fontSize=9.5,leading=14,textColor=green,spaceAfter=8));styles.add(ParagraphStyle(name='SmallOB',fontName='Helvetica',fontSize=8,leading=10,textColor=muted,spaceAfter=5))
def P(text,style='BodyOB'):return Paragraph(text,styles[style])
def table(rows,widths,head=True):
 data=[[P(str(c),'SmallOB') for c in row] for row in rows];t=Table(data,colWidths=widths,hAlign='LEFT');t.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5),('BACKGROUND',(0,0),(-1,0),mint if head else colors.white),('LINEBELOW',(0,0),(-1,-1),.4,colors.HexColor('#c6d4bd'))]));return t
story=[P('OPPORTUNITYBRIDGE / KENNY!','SmallOB'),P('A practical bridge from<br/>learning to civic work.','TitleOB'),P('A manager-ready 60-day pilot proposal for college career services and a city workforce or HR team. No institution or employer has committed.','DeckOB')]
story.append(table([['25 adult learners','25 reviewed opportunities','60 days','$6,240'],['Proposed, voluntary cohort','Independent source checks','Bounded test and report','Total economic estimate']],[129,129,129,129],False))
story += [P('The intervention','HeadOB'),P('Start from a real official opportunity. Make selected requirements and substitutions visible. Help a learner prepare a truthful work sample, open questions and an advisor handoff. Unknown facts remain unknown; the employer determines eligibility.'),P('The college and city have distinct jobs','HeadOB'),table([['Owner','Accountability before launch'],['College career services','Recruit fairly; offer accessible consent and equal human advising; keep scheduling information separate from evaluation IDs.'],['City workforce / HR reviewer','Validate complete source conditions, substitutions and documents; resolve ambiguity; approve or withhold selected mappings.'],['Content steward + maintainer','Keep 25 records current, record review decisions, repair defects and preserve rollback. No automatic date renewal.'],['Evaluator + access reviewer','Freeze equal-information tasks, counterbalance order, score independently and test paper/assistive routes.']],[152,364]),P('Four gates, not an implied partnership','HeadOB'),table([['Days 1-14','Days 15-28','Days 29-56','Days 57-60'],['Agree roles and governance; double-review sources.','Approve consent, accessibility and frozen tasks.','Run voluntary sessions and optional 14-day follow-up.','Report errors, access barriers, workload and go/no-go.']],[129]*4),P('Decision requested','HeadOB'),P('Identify a willing campus lead and municipal reviewer for a scoped co-design conversation. Confirm staff availability, rates and approvals before recruiting. This packet does not request a hiring commitment or claim validated career gains.'),PageBreak(),P('Measure usefulness.<br/>Account for the real cost.','TitleOB'),P('The product can support a test; a polished prototype cannot substitute for independent people, consent and source adjudication.','DeckOB')]
story += [P('What success would mean - proposed thresholds','HeadOB'),table([['Outcome','Measure and safeguard'],['Source correctness','At least 90% correct criterion/source judgments; separately count every missed mandatory condition and false definite eligibility statement (target zero).'],['Actionable plans','At least 80% of task starters score 4/5 on source identity, condition distinction, honest uncertainty, plausible artifact and dated next action. Two blinded raters reconcile.'],['Follow-through','At least 60% of consenting follow-up learners report their chosen next action within 14 days. Distinguish self-report from advisor confirmation.'],['Access and workload','Zero unresolved blocking barriers; median advisor review at most 15 actually measured minutes. Report missing work, assistance and withdrawals.']],[128,388]),P('Budget assumptions (USD)','HeadOB'),table([['Illustrative resource','Hours / assumption','Economic cost'],['Campus lead / advisor','32 h at $50','$1,600'],['Municipal reviewer','16 h at $60','$960'],['Content steward','20 h at $35','$700'],['Technical maintainer','20 h at $60','$1,200'],['Independent evaluator','16 h at $50','$800'],['Accessibility reviewer','8 h at $60','$480'],['Participant compensation + materials/access reserve','25 x $15 plus $125','$500'],['Total','112 staff hours','$6,240']],[228,184,104]),P('<b>Cash envelope: $500 only if all staff labor is contributed.</b> Rates, accommodations and institutional overhead need host confirmation. No funds are committed or spent by this proposal.','SmallOB'),P('Consent, privacy and access','HeadOB'),P('Use fictional tasks and pseudonymous evaluation IDs; collect no private student, patient or job-seeker records in the public app. Participation is voluntary and independent of services. Offer paper/telephone support and devices; test actual assistive technology. Keep contact linkage in approved host systems; delete linkage/raw feedback within 90 days unless approved policy requires otherwise.','SmallOB'),P('Current evidence and honest limits','HeadOB'),P('Independent unfamiliar participants: n=0. No partner commitment, measured hiring effect or causal speed gain. Internal tests verify software behavior. A small pilot would support descriptive findings, not subgroup parity or employment causality.','SmallOB'),P('Source, full plan, consent and rubric: <link href="https://siamakenna.github.io/opportunitybridge-citygov-2026/judge.html" color="#195d40">siamakenna.github.io/opportunitybridge-citygov-2026/judge.html</link>','SmallOB')]
def footer(c,d):
 c.setStrokeColor(green);c.line(48,40,564,40);c.setFont('Helvetica',8);c.setFillColor(muted);c.drawString(48,27,'Proposal only | CityGov 2026 | AI-assisted packet, owner review required');c.drawRightString(564,27,str(d.page))
